-- Colombia: ES/DE/FR milestone translations, hand-written (not the
-- English-placeholder stub) per ADDING-A-COUNTRY.md's translation step.

-- ---- es ----
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('co-large-taxpayers-2018', 'es', 'Resolución 000010 de 2018 (DIAN)', 'La Resolución 000010 de 2018 de la DIAN (6 de febrero de 2018) ordenó a todos los contribuyentes clasificados como "grandes contribuyentes" pasar al sistema de facturación electrónica con validación previa de la DIAN a partir del 1 de septiembre de 2018 -- la primera ola obligatoria de Colombia, apoyada en pilotos voluntarios que se remontan al reconocimiento legal de la factura electrónica en 1995 y al marco del Decreto 2242 de 2015.', '["Obtener un certificado digital acreditado y un software de facturación compatible con DIAN capaz de generar XML basado en UBL.", "Transmitir cada factura a la DIAN para su validación previa en tiempo real antes de entregarla al comprador.", "Conservar las facturas validadas y su registro de aceptación de la DIAN durante al menos 5 años."]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('co-universal-2020', 'es', 'Resolución 000042 de 2020 (DIAN)', 'La Resolución 000042 de 2020 (5 de mayo de 2020) fijó un calendario escalonado que incorporó a los grupos de contribuyentes restantes a la facturación electrónica obligatoria durante 2020; la última ola (Grupos 6, 7 y 8) llegó el 1 de noviembre de 2020, haciendo obligatorio el modelo de validación previa CUFE de la DIAN en tiempo real para prácticamente todo responsable de IVA e INC en Colombia -- cubriendo por igual operaciones B2B, B2C y B2G.', '["Incorporar un software de facturación electrónica certificado antes de la fecha límite de 2020 de su grupo de contribuyentes (última ola: 1 de noviembre).", "Cubrir por igual ventas B2B, B2C y B2G bajo el mismo flujo de validación CUFE.", "Contribuyentes del Régimen Simple (SIMPLE): cumplir dentro de los 2 meses siguientes a la inscripción en lugar de una fecha fija de grupo."]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('co-equivalent-documents-2024', 'es', 'Resolución 000165 de 2023 + Resolución 000008 de 2024 (DIAN)', 'La Resolución 000165 de 2023 (1 de noviembre de 2023) convirtió los "documentos equivalentes" en papel de Colombia -- tickets POS, facturas de servicios públicos, boletos de transporte de pasajeros y aéreos, boletos de juegos de suerte y azar y de peajes -- en documentos electrónicos plenamente validados por la DIAN. La Resolución 000008 de 2024 amplió los plazos originales para dar más tiempo a las empresas; para el 1 de noviembre de 2024 se había convertido ya toda categoría de documento restante (boletos de cine y espectáculos, el último grupo), cerrando así la implementación por fases.', '["Actualizar los sistemas de punto de venta y facturación para generar y transmitir a la DIAN los nuevos formatos de documento equivalente electrónico.", "Cumplir con la fecha límite de 2024 de su categoría de documento (tickets POS desde mayo de 2024 hasta boletos de cine/espectáculos el 1 de noviembre de 2024).", "Usar los tickets POS electrónicos como soporte válido de costos e impuestos sin importar el monto de la operación, conforme a las reglas ampliadas."]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('co-b2c-refinements-2025', 'es', 'Resolución 000202 de 2025 (DIAN)', 'La Resolución 000202 de 2025 (31 de marzo de 2025) refinó el mandato universal ya existente en lugar de ampliar a quién cubre: los comercios ahora pueden capturar únicamente el nombre, tipo/número de identificación y correo electrónico del comprador para facturas de punto de venta (con autocompletado de la DIAN para quienes ya están en su registro), y los prestadores de servicios públicos con problemas reales de conectividad en zonas rurales obtuvieron una ventana de 48 horas para transmitir facturas después de su emisión en lugar de la validación casi en tiempo real habitual de la DIAN.', '["Cambiar la facturación en punto de venta al flujo simplificado de datos del comprador (nombre, tipo/número de identificación, correo electrónico) con autocompletado de la DIAN.", "Prestadores de servicios públicos rurales con conectividad limitada que califiquen: usar la nueva ventana de transmisión de 48 horas en lugar de la validación casi en tiempo real."]');

-- ---- de ----
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('co-large-taxpayers-2018', 'de', 'Resolution 000010 von 2018 (DIAN)', 'Die DIAN-Resolution 000010/2018 (6. Februar 2018) verpflichtete alle als "gran contribuyente" (Großsteuerpflichtiger) eingestuften Steuerzahler, ab dem 1. September 2018 auf das elektronische Rechnungssystem der DIAN mit vorheriger Validierung umzusteigen -- Kolumbiens erste verbindliche Welle, aufbauend auf freiwilligen Pilotprojekten, die bis zur gesetzlichen Anerkennung der elektronischen Rechnung 1995 und dem Rahmenwerk des Decreto 2242/2015 zurückreichen.', '["Ein akkreditiertes digitales Zertifikat und DIAN-konforme Rechnungssoftware beschaffen, die UBL-basiertes XML erzeugen kann.", "Jede Rechnung vor der Übergabe an den Käufer zur Echtzeit-Vorabvalidierung an die DIAN übermitteln.", "Validierte Rechnungen und deren DIAN-Annahmevermerk mindestens 5 Jahre lang aufbewahren."]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('co-universal-2020', 'de', 'Resolution 000042 von 2020 (DIAN)', 'Die Resolution 000042/2020 (5. Mai 2020) legte einen gestaffelten Zeitplan fest, der die verbleibenden Steuerzahlergruppen im Laufe des Jahres 2020 in die verbindliche elektronische Rechnungsstellung einbezog; die letzte Welle (Gruppen 6, 7 und 8) folgte am 1. November 2020, wodurch das Echtzeit-CUFE-Validierungsmodell der DIAN für praktisch jedes mehrwertsteuer- und verbrauchsteuerpflichtige Unternehmen in Kolumbien verbindlich wurde -- gleichermaßen für B2B-, B2C- und B2G-Geschäfte.', '["Zertifizierte Software zur elektronischen Rechnungsstellung vor der 2020-Frist der eigenen Steuerzahlergruppe einführen (letzte Welle: 1. November).", "B2B-, B2C- und B2G-Verkäufe gleichermaßen über denselben CUFE-Validierungsablauf abwickeln.", "Steuerzahler im vereinfachten Regime (SIMPLE): innerhalb von 2 Monaten nach Registrierung statt zu einem festen Gruppentermin compliant werden."]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('co-equivalent-documents-2024', 'de', 'Resolution 000165 von 2023 + Resolution 000008 von 2024 (DIAN)', 'Die Resolution 000165/2023 (1. November 2023) wandelte Kolumbiens papierbasierte "documentos equivalentes" -- Kassenbons, Versorgungsrechnungen, Personen- und Flugtickets, Lotterie- und Mautbelege -- in vollständig elektronische, von der DIAN validierte Dokumente um. Die Resolution 000008/2024 verlängerte die ursprünglichen Fristen, um Unternehmen mehr Zeit zu geben; bis zum 1. November 2024 war jede verbleibende Dokumentkategorie (Kino- und Veranstaltungstickets, die letzte Gruppe) umgestellt und der stufenweise Übergang damit abgeschlossen.', '["Kassen- und Rechnungssysteme aktualisieren, um die neuen elektronischen Formate für gleichwertige Dokumente zu erzeugen und an die DIAN zu übermitteln.", "Die 2024-Frist der eigenen Dokumentkategorie einhalten (Kassenbons ab Mai 2024 bis Kino-/Veranstaltungstickets zum 1. November 2024).", "Elektronische Kassenbons unabhängig vom Transaktionsbetrag als gültigen Kosten- und Steuernachweis nutzen, gemäß den erweiterten Regeln."]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('co-b2c-refinements-2025', 'de', 'Resolution 000202 von 2025 (DIAN)', 'Die Resolution 000202/2025 (31. März 2025) verfeinerte das bereits bestehende universelle Mandat, ohne dessen Geltungsbereich zu erweitern: Einzelhändler dürfen für Kassenrechnungen nun nur noch Name, Ausweisart/-nummer und E-Mail-Adresse des Käufers erfassen (mit automatischer Vervollständigung durch die DIAN für bereits registrierte Personen), und Versorgungsunternehmen mit echten Konnektivitätsproblemen in ländlichen Gebieten erhielten ein 48-Stunden-Fenster zur Übermittlung von Rechnungen nach deren Ausstellung statt der üblichen Nahezu-Echtzeit-Validierung der DIAN.', '["Die Kassenrechnungsstellung auf den vereinfachten Käuferdaten-Ablauf (Name, Ausweisart/-nummer, E-Mail) mit DIAN-Autovervollständigung umstellen.", "Berechtigte ländliche Versorgungsunternehmen mit eingeschränkter Konnektivität: das neue 48-Stunden-Übermittlungsfenster statt der Nahezu-Echtzeit-Validierung nutzen."]');

-- ---- fr ----
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('co-large-taxpayers-2018', 'fr', 'Résolution 000010 de 2018 (DIAN)', 'La résolution 000010 de 2018 de la DIAN (6 février 2018) a imposé à tous les contribuables classés comme "grands contribuables" de passer au système de facturation électronique avec validation préalable de la DIAN à partir du 1er septembre 2018 -- la première vague obligatoire de la Colombie, s''appuyant sur des projets pilotes volontaires remontant à la reconnaissance légale de la facture électronique en 1995 et au cadre du décret 2242 de 2015.', '["Obtenir un certificat numérique accrédité et un logiciel de facturation conforme à la DIAN capable de générer du XML basé sur UBL.", "Transmettre chaque facture à la DIAN pour validation préalable en temps réel avant sa remise à l''acheteur.", "Conserver les factures validées et leur accusé de réception de la DIAN pendant au moins 5 ans."]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('co-universal-2020', 'fr', 'Résolution 000042 de 2020 (DIAN)', 'La résolution 000042 de 2020 (5 mai 2020) a fixé un calendrier échelonné intégrant les groupes de contribuables restants à la facturation électronique obligatoire au cours de 2020 ; la dernière vague (groupes 6, 7 et 8) est arrivée le 1er novembre 2020, rendant le modèle de validation CUFE en temps réel de la DIAN obligatoire pour pratiquement toute entreprise assujettie à la TVA ou à la taxe de consommation nationale en Colombie -- couvrant aussi bien les opérations B2B, B2C que B2G.', '["Mettre en place un logiciel de facturation électronique certifié avant l''échéance 2020 de son groupe de contribuables (dernière vague : 1er novembre).", "Couvrir aussi bien les ventes B2B, B2C que B2G via le même flux de validation CUFE.", "Contribuables du régime simplifié (SIMPLE) : se mettre en conformité dans les 2 mois suivant l''inscription plutôt qu''à une date de groupe fixe."]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('co-equivalent-documents-2024', 'fr', 'Résolution 000165 de 2023 + Résolution 000008 de 2024 (DIAN)', 'La résolution 000165 de 2023 (1er novembre 2023) a converti les "documents équivalents" papier de la Colombie -- tickets de caisse, factures de services publics, billets de transport de passagers et aériens, billets de jeux de hasard et de péage -- en documents électroniques entièrement validés par la DIAN. La résolution 000008 de 2024 a prolongé les délais initiaux pour laisser plus de temps aux entreprises ; au 1er novembre 2024, chaque catégorie de document restante (billets de cinéma et de spectacles, le dernier groupe) avait été convertie, clôturant ainsi la mise en œuvre progressive.', '["Mettre à jour les systèmes de caisse et de facturation pour générer et transmettre à la DIAN les nouveaux formats de documents équivalents électroniques.", "Respecter l''échéance 2024 de sa catégorie de document (tickets de caisse à partir de mai 2024 jusqu''aux billets de cinéma/spectacles au 1er novembre 2024).", "Utiliser les tickets de caisse électroniques comme justificatif valable de coûts et de taxes quel que soit le montant de l''opération, conformément aux règles élargies."]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('co-b2c-refinements-2025', 'fr', 'Résolution 000202 de 2025 (DIAN)', 'La résolution 000202 de 2025 (31 mars 2025) a affiné le mandat universel déjà en vigueur sans en élargir le périmètre : les commerçants peuvent désormais ne recueillir que le nom, le type/numéro de pièce d''identité et l''e-mail de l''acheteur pour les factures en point de vente (avec saisie automatique par la DIAN pour les personnes déjà enregistrées), et les prestataires de services publics confrontés à de réels problèmes de connectivité en zone rurale ont obtenu une fenêtre de 48 heures pour transmettre leurs factures après émission au lieu de la validation quasi en temps réel habituelle de la DIAN.', '["Faire passer la facturation en point de vente au flux simplifié de données acheteur (nom, type/numéro de pièce d''identité, e-mail) avec saisie automatique DIAN.", "Prestataires de services publics ruraux à connectivité limitée éligibles : utiliser la nouvelle fenêtre de transmission de 48 heures au lieu de la validation quasi en temps réel."]');
